create extension if not exists "pgcrypto";
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text,role text not null default 'tenant' check(role in ('tenant','owner','admin')),mobile text,created_at timestamptz not null default now());
create table if not exists public.properties(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,title text not null,property_type text not null,area text not null,location text,rent numeric not null,deposit numeric default 0,availability_date date,furnishing text default 'Furnished',sharing_type text default 'Private',description text,amenities text[] default '{}',status text not null default 'pending' check(status in ('pending','active','rented','rejected')),verification_status text not null default 'Unverified',last_verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.property_images(id uuid primary key default gen_random_uuid(),property_id uuid references public.properties(id) on delete cascade,image_url text not null,created_at timestamptz not null default now());
create table if not exists public.favorites(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,property_id uuid references public.properties(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,property_id));
create table if not exists public.enquiries(id uuid primary key default gen_random_uuid(),property_id uuid references public.properties(id) on delete cascade,user_id uuid references public.profiles(id) on delete set null,name text not null,mobile text not null,move_in_date date,message text,created_at timestamptz not null default now());
create table if not exists public.availability_updates(id uuid primary key default gen_random_uuid(),property_id uuid references public.properties(id) on delete cascade,owner_id uuid references public.profiles(id) on delete cascade,available boolean not null,created_at timestamptz not null default now());
create table if not exists public.areas(id uuid primary key default gen_random_uuid(),name text unique not null,active boolean default false,created_at timestamptz not null default now());
create table if not exists public.search_logs(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete set null,area text,property_type text,max_rent numeric,had_results boolean,created_at timestamptz not null default now());
create table if not exists public.area_demand(id uuid primary key default gen_random_uuid(),area text unique not null,search_count integer not null default 0,no_result_count integer not null default 0,listing_count integer not null default 0,enquiry_count integer not null default 0,updated_at timestamptz not null default now());
insert into public.areas(name,active) values('Wakad',true),('Bhumkar Chowk',true),('Dange Chowk',true),('Hinjewadi Phase 1',true),('Hinjewadi Phase 2',true),('Hinjewadi Phase 3',true),('Marunji',true) on conflict(name) do update set active=excluded.active;
alter table public.profiles enable row level security; alter table public.properties enable row level security; alter table public.property_images enable row level security; alter table public.favorites enable row level security; alter table public.enquiries enable row level security; alter table public.availability_updates enable row level security; alter table public.areas enable row level security; alter table public.search_logs enable row level security; alter table public.area_demand enable row level security;
create policy "Public can read active properties" on public.properties for select using(status='active' or owner_id=auth.uid());
create policy "Owners can insert own properties" on public.properties for insert with check(owner_id=auth.uid());
create policy "Owners can update own properties" on public.properties for update using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "Users can read active areas" on public.areas for select using(active=true);
create policy "Users can create own profile" on public.profiles for insert with check(id=auth.uid());
create policy "Users can read own profile" on public.profiles for select using(id=auth.uid());
create policy "Users can update own profile" on public.profiles for update using(id=auth.uid());
create policy "Users manage own favorites" on public.favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "Users create enquiries" on public.enquiries for insert with check(user_id=auth.uid());
create policy "Owners read enquiries for own properties" on public.enquiries for select using(exists(select 1 from public.properties p where p.id=property_id and p.owner_id=auth.uid()));
create policy "Owners insert availability updates" on public.availability_updates for insert with check(owner_id=auth.uid());
create policy "Anyone can create search logs" on public.search_logs for insert with check(user_id=auth.uid() or user_id is null);
-- Add stricter server-side admin authorization before production. Never expose service_role in frontend.